bool Read_DrawBuildSquareQuery(const WasmValue& input, DrawBuildSquareQuery& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_unitDefID = FindRecordField(*record, "unit-def-id", error);
	if (value_unitDefID == nullptr) return false;
	if (!ReadScalar(*value_unitDefID, output.unitDefID, error)) { return false; }
	const auto* value_x = FindRecordField(*record, "x", error);
	if (value_x == nullptr) return false;
	if (!ReadScalar(*value_x, output.x, error)) { return false; }
	const auto* value_z = FindRecordField(*record, "z", error);
	if (value_z == nullptr) return false;
	if (!ReadScalar(*value_z, output.z, error)) { return false; }
	const auto* value_facing = FindRecordField(*record, "facing", error);
	if (value_facing == nullptr) return false;
	if (!ReadScalar(*value_facing, output.facing, error)) { return false; }
	const auto* value_statuses = FindRecordField(*record, "statuses", error);
	if (value_statuses == nullptr) return false;
	auto& native_statuses = storage.Make<std::vector<std::uint8_t>>();
	if (!ReadByteList(*value_statuses, native_statuses, error)) { return false; }
	output.statuses = reinterpret_cast<decltype(output.statuses)>(native_statuses.data());
	if (!AssignCount(native_statuses.size(), output.statusCount, error)) { return false; }
	return true;
}

WasmValue Write_DrawBuildSquareQuery(const DrawBuildSquareQuery& value)
{
	WasmValueRecord fields;
	fields.emplace("unit-def-id", WriteScalar(value.unitDefID));
	fields.emplace("x", WriteScalar(value.x));
	fields.emplace("z", WriteScalar(value.z));
	fields.emplace("facing", WriteScalar(value.facing));
	fields.emplace("statuses", WriteNativeList(value.statuses, value.statusCount, [](const auto& value) { return WriteScalar(value); }));
	return WasmValue::Record(std::move(fields));
}

